def mkgrid(h,w,rect,marks):
    g=[[0]*w for _ in range(h)]
    a,b,c,d=rect
    for r in range(a,b+1):
        for col in range(c,d+1):g[r][col]=2
    for r,col,color in marks:g[r][col]=color
    return g

def expected_from_specs(inp, rowspans=(), colstripes=()):
    e=[r[:] for r in inp]
    for r, intervals in rowspans:
        for a,b in intervals:
            for c in range(a,b+1):
                if e[r][c]==0:e[r][c]=2
    for c, intervals in colstripes:
        for a,b in intervals:
            for r in range(a,b+1):
                if e[r][c]==0:e[r][c]=2
    return e

